/**
 * spritegen.js — procedural pixel-art sprites for heroes, monsters, NPCs,
 * items and props. Every sprite is painted from code into small canvases at
 * boot: the whole art set costs zero download and a few hundred KB of RAM.
 *
 * Sprites are 16×24 (characters) or 16×16 (props/icons) with 2-4 frame
 * walk cycles generated by shifting limb pixels.
 */
import { PALETTE, shade } from './palette.js';
import { hash2 } from '../core/mathx.js';

function makeCanvas(w, h) {
  if (typeof document === 'undefined' || typeof document.createElement !== 'function') {
    return { width: w, height: h, getContext: () => makeFakeCtx(), __stub: true };
  }
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  return c;
}

function makeFakeCtx() {
  const noop = () => undefined;
  return new Proxy({}, {
    get: (target, prop) => (prop === 'canvas' ? { width: 16, height: 24 } : noop),
    set: () => true,
  });
}

// ------------------------------------------------------------------ helpers

function px(ctx, x, y, w, h, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x, y, w, h);
}

function outlineRect(ctx, x, y, w, h, color) {
  px(ctx, x, y, w, 1, color);
  px(ctx, x, y + h - 1, w, 1, color);
  px(ctx, x, y, 1, h, color);
  px(ctx, x + w - 1, y, 1, h, color);
}

/**
 * Shared humanoid painter. Frame 0 = idle, 1-2 = walk cycle, 3 = attack.
 * `colors` describes skin, cloth, accent, hair, boots.
 */
function paintHumanoid(ctx, colors, frame, opts = {}) {
  const {
    skin = '#e8b88a',
    cloth = '#4a6fa5',
    clothDark = null,
    accent = '#e8b64c',
    hair = '#2c1808',
    boots = '#4a2c18',
    cape = null,
    hood = false,
    weapon = null,
    shield = false,
  } = colors;
  const clothShade = clothDark || shade(cloth, -0.3);
  const walk = frame === 1 ? 1 : frame === 2 ? -1 : 0;
  const bob = frame === 1 || frame === 2 ? 1 : 0;

  // shadow
  px(ctx, 3, 22, 10, 2, 'rgba(0,0,0,0.3)');

  if (cape) {
    px(ctx, 3, 8 + bob, 2, 11, cape);
    px(ctx, 11, 8 + bob, 2, 11, shade(cape, -0.2));
    if (walk !== 0) px(ctx, 3 + walk, 14, 2, 5, shade(cape, 0.1));
  }

  // legs
  const legY = 16 + bob;
  px(ctx, 5, legY, 3, 5, clothShade);
  px(ctx, 8, legY, 3, 5, clothShade);
  if (walk === 1) {
    px(ctx, 4, legY + 2, 3, 4, clothShade);
    px(ctx, 5, legY + 5, 3, 2, boots);
    px(ctx, 9, legY + 4, 3, 2, boots);
  } else if (walk === -1) {
    px(ctx, 9, legY + 2, 3, 4, clothShade);
    px(ctx, 8, legY + 5, 3, 2, boots);
    px(ctx, 5, legY + 4, 3, 2, boots);
  } else {
    px(ctx, 5, legY + 5, 3, 2, boots);
    px(ctx, 8, legY + 5, 3, 2, boots);
  }

  // torso
  px(ctx, 4, 9 + bob, 8, 8, cloth);
  px(ctx, 4, 9 + bob, 8, 1, shade(cloth, 0.15));
  px(ctx, 4, 15 + bob, 8, 2, clothShade);
  // belt
  px(ctx, 4, 14 + bob, 8, 1, accent);

  // arms
  const armSwing = frame === 3 ? -3 : walk;
  px(ctx, 2, 10 + bob + armSwing, 2, 6, cloth);
  px(ctx, 12, 10 + bob - armSwing, 2, 6, cloth);
  px(ctx, 2, 15 + bob + armSwing, 2, 2, skin);
  px(ctx, 12, 15 + bob - armSwing, 2, 2, skin);

  // head
  const headY = 2 + bob;
  px(ctx, 5, headY, 6, 6, skin);
  px(ctx, 5, headY + 5, 6, 1, shade(skin, -0.15));
  // eyes
  px(ctx, 6, headY + 2, 1, 2, '#1a1220');
  px(ctx, 9, headY + 2, 1, 2, '#1a1220');

  if (hood) {
    px(ctx, 4, headY - 1, 8, 3, cloth);
    px(ctx, 4, headY, 1, 5, cloth);
    px(ctx, 11, headY, 1, 5, cloth);
    px(ctx, 5, headY, 6, 1, clothShade);
  } else {
    // hair
    px(ctx, 5, headY - 1, 6, 2, hair);
    px(ctx, 4, headY, 1, 3, hair);
    px(ctx, 11, headY, 1, 3, hair);
    if (colors.longHair) px(ctx, 4, headY + 3, 1, 4, hair);
    if (colors.beard) px(ctx, 6, headY + 5, 4, 2, hair);
  }

  // weapon
  if (weapon === 'sword') {
    const wx = frame === 3 ? 13 : 12;
    const wy = frame === 3 ? 6 : 11 + bob - armSwing;
    px(ctx, wx, wy, 1, 7, '#c8ccd4');
    px(ctx, wx, wy, 1, 2, '#eef1f4');
    px(ctx, wx - 1, wy + 6, 3, 1, '#8a6a42');
  } else if (weapon === 'staff') {
    px(ctx, 13, 6 + bob, 1, 12, '#6e4a22');
    px(ctx, 12, 4 + bob, 3, 3, accent);
    px(ctx, 13, 5 + bob, 1, 1, shade(accent, 0.5));
  } else if (weapon === 'bow') {
    outlineRect(ctx, 12, 8 + bob, 3, 8, '#8a6a42');
    px(ctx, 13, 8 + bob, 1, 8, '#e8e2d0');
  } else if (weapon === 'dagger') {
    px(ctx, 13, 12 + bob, 1, 4, '#c8ccd4');
    px(ctx, 12, 15 + bob, 3, 1, '#8a6a42');
  }

  if (shield) {
    px(ctx, 1, 11 + bob, 3, 5, accent);
    px(ctx, 1, 11 + bob, 3, 1, shade(accent, 0.3));
    px(ctx, 2, 13 + bob, 1, 2, shade(accent, -0.35));
  }

  if (opts.helmet) {
    px(ctx, 4, headY - 1, 8, 3, '#b8bcc4');
    px(ctx, 5, headY + 1, 6, 1, '#8a8e96');
    px(ctx, 7, headY + 2, 2, 2, '#1a1220');
  }
}

/**
 * Bestiary painter — stylized critters. Each recipe is a small pixel
 * routine keyed by family: insect, reptile, spirit, beast, elemental, humanoid.
 */
function paintCreature(ctx, family, colors, frame) {
  const { body, dark, light, eye = '#1a1220' } = colors;
  const wiggle = frame % 2 === 1 ? 1 : 0;

  px(ctx, 3, 21, 10, 2, 'rgba(0,0,0,0.3)');

  switch (family) {
    case 'insect': {
      // scorpion-like
      px(ctx, 4, 12 + wiggle, 9, 7, body);
      px(ctx, 4, 12 + wiggle, 9, 1, light);
      px(ctx, 4, 18, 9, 1, dark);
      px(ctx, 3, 14, 2, 4, body);
      px(ctx, 12, 14, 2, 4, body);
      // tail
      px(ctx, 12, 8 + wiggle, 2, 5, dark);
      px(ctx, 13, 6 + wiggle, 2, 3, body);
      px(ctx, 13, 5 + wiggle, 2, 1, light);
      // claws
      px(ctx, 2, 11 + wiggle, 3, 2, dark);
      px(ctx, 12, 11 + wiggle, 3, 2, dark);
      // eyes
      px(ctx, 6, 14 + wiggle, 1, 1, eye);
      px(ctx, 9, 14 + wiggle, 1, 1, eye);
      // legs
      px(ctx, 5, 19, 1, 2, dark);
      px(ctx, 8, 19, 1, 2, dark);
      px(ctx, 11, 19, 1, 2, dark);
      break;
    }
    case 'reptile': {
      // serpent / lizard
      const coil = wiggle * 2;
      px(ctx, 3, 13, 11, 6, body);
      px(ctx, 3, 13, 11, 1, light);
      px(ctx, 4, 18, 10, 1, dark);
      px(ctx, 2 + coil, 15, 3, 3, body);
      px(ctx, 12 - coil, 12, 3, 4, body);
      px(ctx, 13, 10 - wiggle, 2, 3, dark);
      px(ctx, 13, 9 - wiggle, 1, 1, light);
      px(ctx, 5, 15, 2, 1, eye);
      px(ctx, 9, 15, 2, 1, eye);
      px(ctx, 4, 19, 2, 2, dark);
      px(ctx, 10, 19, 2, 2, dark);
      break;
    }
    case 'spirit': {
      // floating wraith — translucent-ish via lighter colors
      const hover = wiggle * 2;
      px(ctx, 5, 4 + hover, 6, 8, body);
      px(ctx, 4, 6 + hover, 8, 6, body);
      px(ctx, 5, 4 + hover, 6, 1, light);
      // tattered lower body
      px(ctx, 5, 13 + hover, 2, 5, dark);
      px(ctx, 8, 14 + hover, 2, 4, dark);
      px(ctx, 10, 13 + hover, 1, 3, dark);
      // arms
      px(ctx, 2, 8 + hover, 3, 2, body);
      px(ctx, 11, 8 + hover, 3, 2, body);
      // eyes glow
      px(ctx, 6, 8 + hover, 2, 2, light);
      px(ctx, 9, 8 + hover, 2, 2, light);
      px(ctx, 6, 8 + hover, 1, 1, eye);
      px(ctx, 10, 8 + hover, 1, 1, eye);
      break;
    }
    case 'beast': {
      // jackal / hyena
      px(ctx, 3, 12, 11, 7, body);
      px(ctx, 3, 12, 11, 1, light);
      px(ctx, 3, 18, 11, 1, dark);
      // head
      px(ctx, 11, 8 + wiggle, 4, 5, body);
      px(ctx, 14, 10 + wiggle, 2, 2, dark);
      px(ctx, 12, 7 + wiggle, 2, 2, dark);
      px(ctx, 12, 9 + wiggle, 1, 1, eye);
      // legs
      px(ctx, 4, 18, 2, 3, dark);
      px(ctx, 7, 19, 2, 2, dark);
      px(ctx, 10, 18, 2, 3, dark);
      // tail
      px(ctx, 1, 13 + wiggle, 3, 2, dark);
      break;
    }
    case 'elemental': {
      // sand golem / crystal
      px(ctx, 4, 8, 8, 11, body);
      px(ctx, 3, 10, 2, 7, dark);
      px(ctx, 11, 10, 2, 7, dark);
      px(ctx, 5, 5 + wiggle, 6, 4, body);
      px(ctx, 5, 5 + wiggle, 6, 1, light);
      px(ctx, 6, 11, 4, 4, light);
      px(ctx, 7, 12, 2, 2, eye);
      px(ctx, 4, 18, 3, 3, dark);
      px(ctx, 9, 18, 3, 3, dark);
      break;
    }
    case 'bossWraith': {
      // large wraith — 16x24
      const hover = wiggle * 2;
      px(ctx, 3, 2 + hover, 10, 10, body);
      px(ctx, 2, 5 + hover, 12, 8, body);
      px(ctx, 3, 2 + hover, 10, 2, light);
      px(ctx, 3, 13 + hover, 3, 8, dark);
      px(ctx, 7, 14 + hover, 3, 7, dark);
      px(ctx, 11, 13 + hover, 2, 6, dark);
      px(ctx, 0, 7 + hover, 3, 3, body);
      px(ctx, 13, 7 + hover, 3, 3, body);
      px(ctx, 4, 7 + hover, 3, 3, light);
      px(ctx, 9, 7 + hover, 3, 3, light);
      px(ctx, 5, 8 + hover, 1, 1, eye);
      px(ctx, 10, 8 + hover, 1, 1, eye);
      // horns
      px(ctx, 3, 0 + hover, 2, 3, dark);
      px(ctx, 11, 0 + hover, 2, 3, dark);
      break;
    }
    case 'bossGolem': {
      px(ctx, 2, 6, 12, 13, body);
      px(ctx, 1, 8, 2, 9, dark);
      px(ctx, 13, 8, 2, 9, dark);
      px(ctx, 4, 3, 8, 5, body);
      px(ctx, 4, 3, 8, 1, light);
      px(ctx, 5, 10, 6, 5, light);
      px(ctx, 7, 11, 2, 3, eye);
      px(ctx, 3, 18, 4, 3, dark);
      px(ctx, 9, 18, 4, 3, dark);
      // cracks glow
      px(ctx, 6, 7, 1, 4, light);
      px(ctx, 10, 13, 1, 5, light);
      break;
    }
    case 'giant': {
      // giant scorpion boss
      px(ctx, 1, 10, 14, 9, body);
      px(ctx, 1, 10, 14, 1, light);
      px(ctx, 1, 18, 14, 1, dark);
      px(ctx, 13, 3 + wiggle, 3, 8, dark);
      px(ctx, 14, 0 + wiggle, 2, 4, body);
      px(ctx, 14, -1 + wiggle, 2, 2, light);
      px(ctx, 0, 8, 3, 3, dark);
      px(ctx, 13, 8, 3, 3, dark);
      px(ctx, 3, 12, 2, 2, eye);
      px(ctx, 8, 12, 2, 2, eye);
      px(ctx, 2, 19, 2, 2, dark);
      px(ctx, 7, 19, 2, 2, dark);
      px(ctx, 12, 19, 2, 2, dark);
      break;
    }
    case 'npc':
    case 'humanoid':
    default: {
      paintHumanoid(ctx, { ...colors, cloth: body, clothDark: dark }, frame, {});
      break;
    }
  }
}

/** Item icons — 16×16. */
function paintItemIcon(ctx, kind, colors = {}) {
  const main = colors.main || '#c8ccd4';
  const accent = colors.accent || '#e8b64c';
  const dark = colors.dark || '#6e5230';
  px(ctx, 0, 0, 16, 16, 'rgba(0,0,0,0)');
  switch (kind) {
    case 'sword': {
      px(ctx, 7, 1, 2, 10, main);
      px(ctx, 7, 1, 1, 10, shade(main, 0.35));
      px(ctx, 5, 11, 6, 1, accent);
      px(ctx, 7, 12, 2, 3, dark);
      break;
    }
    case 'axe': {
      px(ctx, 7, 3, 2, 11, dark);
      px(ctx, 4, 2, 6, 4, main);
      px(ctx, 4, 2, 6, 1, shade(main, 0.3));
      break;
    }
    case 'staff': {
      px(ctx, 7, 3, 2, 12, dark);
      px(ctx, 5, 1, 6, 4, accent);
      px(ctx, 7, 2, 2, 2, shade(accent, 0.5));
      break;
    }
    case 'bow': {
      outlineRect(ctx, 4, 2, 8, 12, dark);
      px(ctx, 8, 3, 1, 10, '#e8e2d0');
      break;
    }
    case 'dagger': {
      px(ctx, 7, 3, 2, 7, main);
      px(ctx, 5, 10, 6, 1, accent);
      px(ctx, 7, 11, 2, 3, dark);
      break;
    }
    case 'shield': {
      px(ctx, 4, 2, 8, 10, main);
      px(ctx, 4, 2, 8, 2, shade(main, 0.25));
      px(ctx, 6, 5, 4, 4, accent);
      px(ctx, 4, 11, 8, 2, dark);
      break;
    }
    case 'armor': {
      px(ctx, 4, 3, 8, 10, main);
      px(ctx, 3, 4, 2, 5, main);
      px(ctx, 11, 4, 2, 5, main);
      px(ctx, 5, 3, 6, 2, shade(main, 0.25));
      px(ctx, 6, 7, 4, 1, accent);
      break;
    }
    case 'helmet': {
      px(ctx, 4, 4, 8, 7, main);
      px(ctx, 5, 3, 6, 2, shade(main, 0.25));
      px(ctx, 6, 7, 4, 2, dark);
      break;
    }
    case 'boots': {
      px(ctx, 5, 4, 3, 8, dark);
      px(ctx, 9, 4, 3, 8, dark);
      px(ctx, 4, 11, 4, 2, main);
      px(ctx, 9, 11, 4, 2, main);
      break;
    }
    case 'ring': {
      outlineRect(ctx, 5, 5, 7, 7, accent);
      px(ctx, 7, 3, 3, 3, main);
      break;
    }
    case 'potion': {
      px(ctx, 6, 2, 4, 2, dark);
      px(ctx, 5, 4, 6, 10, main);
      px(ctx, 6, 5, 4, 8, shade(main, 0.3));
      px(ctx, 6, 8, 2, 3, '#ffffff');
      break;
    }
    case 'food': {
      px(ctx, 3, 6, 10, 7, main);
      px(ctx, 4, 5, 8, 2, shade(main, 0.25));
      px(ctx, 6, 8, 4, 2, accent);
      break;
    }
    case 'scroll': {
      px(ctx, 4, 3, 8, 10, '#e8e2d0');
      px(ctx, 4, 3, 8, 2, dark);
      px(ctx, 4, 11, 8, 2, dark);
      px(ctx, 6, 6, 4, 1, '#8a6a42');
      px(ctx, 6, 8, 4, 1, '#8a6a42');
      break;
    }
    case 'gem': {
      px(ctx, 6, 3, 4, 9, main);
      px(ctx, 4, 6, 8, 4, main);
      px(ctx, 7, 4, 2, 6, shade(main, 0.45));
      break;
    }
    case 'key': {
      px(ctx, 4, 4, 5, 5, accent);
      px(ctx, 5, 5, 3, 3, dark);
      px(ctx, 8, 8, 2, 6, accent);
      px(ctx, 10, 12, 3, 1, accent);
      px(ctx, 10, 10, 2, 1, accent);
      break;
    }
    case 'coin': {
      px(ctx, 4, 5, 8, 7, accent);
      px(ctx, 5, 4, 6, 9, accent);
      px(ctx, 6, 6, 4, 5, shade(accent, 0.35));
      break;
    }
    case 'material': {
      px(ctx, 4, 5, 8, 8, main);
      px(ctx, 5, 4, 6, 2, shade(main, 0.25));
      px(ctx, 6, 7, 2, 2, dark);
      px(ctx, 9, 9, 2, 2, dark);
      break;
    }
    case 'book': {
      px(ctx, 3, 3, 10, 11, main);
      px(ctx, 3, 3, 10, 2, shade(main, 0.25));
      px(ctx, 5, 7, 6, 1, accent);
      px(ctx, 5, 9, 6, 1, accent);
      px(ctx, 3, 3, 2, 11, dark);
      break;
    }
    case 'amulet': {
      px(ctx, 5, 2, 6, 1, accent);
      px(ctx, 4, 3, 1, 5, accent);
      px(ctx, 11, 3, 1, 5, accent);
      px(ctx, 6, 8, 4, 5, main);
      px(ctx, 7, 9, 2, 2, shade(main, 0.5));
      break;
    }
    default: {
      px(ctx, 4, 4, 8, 8, main);
      px(ctx, 5, 5, 6, 6, accent);
      break;
    }
  }
}

// ------------------------------------------------------------- sprite cache

export class SpriteBank {
  constructor() {
    this.cache = new Map();
  }

  _key(parts) {
    return parts.join('|');
  }

  _build(key, w, h, painter) {
    let sprite = this.cache.get(key);
    if (!sprite) {
      sprite = makeCanvas(w, h);
      const ctx = sprite.getContext('2d');
      painter(ctx);
      this.cache.set(key, sprite);
    }
    return sprite;
  }

  /** Character sprite: returns canvas 16×24. */
  character(id, colors, frame = 0, opts = {}) {
    const key = this._key(['char', id, frame, JSON.stringify(colors), JSON.stringify(opts)]);
    return this._build(key, 16, 24, (ctx) => paintHumanoid(ctx, colors, frame, opts));
  }

  /** Creature sprite from the bestiary. */
  creature(id, family, colors, frame = 0) {
    const key = this._key(['cre', id, family, frame, JSON.stringify(colors)]);
    return this._build(key, 16, 24, (ctx) => paintCreature(ctx, family, colors, frame));
  }

  /** Item icon 16×16. */
  icon(kind, colors = {}) {
    const key = this._key(['icon', kind, JSON.stringify(colors)]);
    return this._build(key, 16, 16, (ctx) => paintItemIcon(ctx, kind, colors));
  }

  /** Simple prop (torch flame flicker frame, cactus, rock chunk, coin pile). */
  prop(id, painter, w = 16, h = 16) {
    const key = this._key(['prop', id, w, h]);
    return this._build(key, w, h, painter);
  }

  /** Boss sprites are just creature sprites with bigger canvases. */
  boss(id, family, colors, frame = 0) {
    const key = this._key(['boss', id, family, frame, JSON.stringify(colors)]);
    return this._build(key, 16, 24, (ctx) => paintCreature(ctx, family, colors, frame));
  }

  clear() {
    this.cache.clear();
  }

  get count() {
    return this.cache.size;
  }
}

